CREATE TABLE "VisibilityPanel"("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"siteId" TEXT NOT NULL,"version" INTEGER NOT NULL,"prompts" JSONB NOT NULL,"brands" JSONB NOT NULL,"createdBy" TEXT NOT NULL,"reviewedBy" TEXT,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("workspaceId","siteId","version"),UNIQUE("workspaceId","siteId","id"),FOREIGN KEY("workspaceId","siteId") REFERENCES "Site"("workspaceId","id") ON DELETE CASCADE);
CREATE TABLE "VisibilityRun"("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"siteId" TEXT NOT NULL,"panelId" TEXT NOT NULL,"profile" TEXT NOT NULL CHECK("profile" IN ('azure-sol-api','consumer-chatgpt','consumer-gemini')),"cohort" TEXT NOT NULL,"provenance" JSONB NOT NULL,"slots" JSONB NOT NULL,"rawAnswers" JSONB,"rawExpiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("workspaceId","siteId","panelId") REFERENCES "VisibilityPanel"("workspaceId","siteId","id") ON DELETE CASCADE);
CREATE INDEX "VisibilityRun_workspaceId_siteId_createdAt_idx" ON "VisibilityRun"("workspaceId","siteId","createdAt");
CREATE FUNCTION immutable_visibility_panel() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
IF ROW(NEW."id",NEW."workspaceId",NEW."siteId",NEW."version",NEW."prompts",NEW."brands",NEW."createdBy",NEW."createdAt") IS DISTINCT FROM ROW(OLD."id",OLD."workspaceId",OLD."siteId",OLD."version",OLD."prompts",OLD."brands",OLD."createdBy",OLD."createdAt") OR OLD."reviewedAt" IS NOT NULL THEN RAISE EXCEPTION 'IMMUTABLE_PANEL'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_visibility_panel BEFORE UPDATE ON "VisibilityPanel" FOR EACH ROW EXECUTE FUNCTION immutable_visibility_panel();
DO $$ DECLARE t text; r text; BEGIN FOREACH t IN ARRAY ARRAY['VisibilityPanel','VisibilityRun'] LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
EXECUTE format('CREATE POLICY workspace_scope ON %I USING ("workspaceId"=current_setting(''app.workspace_id'',true)) WITH CHECK ("workspaceId"=current_setting(''app.workspace_id'',true))',t);
EXECUTE format('REVOKE ALL ON %I FROM PUBLIC',t);
FOREACH r IN ARRAY ARRAY['anon','authenticated'] LOOP IF EXISTS(SELECT FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON %I FROM %I',t,r); END IF; END LOOP; END LOOP;
IF EXISTS(SELECT FROM pg_roles WHERE rolname='lyraseo_runtime') THEN GRANT SELECT,INSERT,UPDATE ON "VisibilityPanel" TO lyraseo_runtime; GRANT SELECT,INSERT ON "VisibilityRun" TO lyraseo_runtime; END IF; END $$;
